29	Df::Df(const int argc, char **argv) : HdfsTool(argc, argv) {}
30	
31	bool Df::Initialize() {
32	  auto add_options = opt_desc_.add_options();
33	  add_options("help,h", "Displays size, used space, and available space of "
34	                        "the entire filesystem where PATH is located");
35	  add_options("path", po::value<std::string>(),
36	              "The path indicating the filesystem that needs to be df-ed");
37	
38	  // We allow only one argument to be passed to this tool. An exception is
39	  // thrown if multiple arguments are passed.
40	  pos_opt_desc_.add("path", 1);
41	
42	  po::store(po::command_line_parser(argc_, argv_)
43	                .options(opt_desc_)
44	                .positional(pos_opt_desc_)
45	                .run(),
46	            opt_val_);
47	  po::notify(opt_val_);
48	  return true;
49	}
50	
51	std::string Df::GetDescription() const {
52	  std::stringstream desc;
53	  desc << "Usage: hdfs_df [OPTION] PATH" << std::endl
54	       << std::endl
55	       << "Displays size, used space, and available space of" << std::endl
56	       << "the entire filesystem where PATH is located" << std::endl
57	       << std::endl
58	       << "  -h        display this help and exit" << std::endl
59	       << std::endl
60	       << "Examples:" << std::endl
61	       << "hdfs_df hdfs://localhost.localdomain:8020/" << std::endl
62	       << "hdfs_df /" << std::endl;
63	  return desc.str();
64	}
65	
66	bool Df::Do() {
67	  if (!Initialize()) {
68	    std::cerr << "Unable to initialize HDFS df tool" << std::endl;
69	    return false;
70	  }
71	
72	  if (!ValidateConstraints()) {
73	    std::cout << GetDescription();
74	    return false;
75	  }
76	
77	  if (opt_val_.count("help") > 0) {
78	    return HandleHelp();
79	  }
80	
81	  if (opt_val_.count("path") > 0) {
82	    const auto path = opt_val_["path"].as<std::string>();
83	    return HandlePath(path);
84	  }
85	
86	  return true;
87	}
88	
89	bool Df::HandleHelp() const {
90	  std::cout << GetDescription();
91	  return true;
92	}
93	
94	bool Df::HandlePath(const std::string &path) const {
95	  // Building a URI object from the given uri_path
96	  auto uri = hdfs::parse_path_or_exit(path);
97	
98	  const auto fs = hdfs::doConnect(uri, false);
99	  if (!fs) {
100	    std::cerr << "Error: Could not connect the file system." << std::endl;
101	    return false;
102	  }
103	
104	  hdfs::FsInfo fs_info;
105	  const auto status = fs->GetFsStats(fs_info);
106	  if (!status.ok()) {
107	    std::cerr << "Error: " << status.ToString() << std::endl;
108	    return false;
109	  }
110	  std::cout << fs_info.str("hdfs://" + fs->get_cluster_name()) << std::endl;
111	  return true;
112	}
113	} // namespace hdfs::tools

