24	
25	void usage(){
26	  std::cout << "Usage: hdfs_du [OPTION] PATH"
27	      << std::endl
28	      << std::endl << "Displays sizes of files and directories contained in the given PATH"
29	      << std::endl << "or the length of a file in case PATH is just a file"
30	      << std::endl
31	      << std::endl << "  -R        operate on files and directories recursively"
32	      << std::endl << "  -h        display this help and exit"
33	      << std::endl
34	      << std::endl << "Examples:"
35	      << std::endl << "hdfs_du hdfs://localhost.localdomain:8020/dir/file"
36	      << std::endl << "hdfs_du -R /dir1/dir2"
37	      << std::endl;
38	}
39	
40	struct GetContentSummaryState {
41	  const std::function<void(const hdfs::Status &)> handler;
42	  //The request counter is incremented once every time GetContentSummary async call is made
43	  uint64_t request_counter;
44	  //This boolean will be set when find returns the last result
45	  bool find_is_done;
46	  //Final status to be returned
47	  hdfs::Status status;
48	  //Shared variables will need protection with a lock
49	  std::mutex lock;
50	  GetContentSummaryState(const std::function<void(const hdfs::Status &)> & handler_,
51	              uint64_t request_counter_, bool find_is_done_)
52	      : handler(handler_),
53	        request_counter(request_counter_),
54	        find_is_done(find_is_done_),
55	        status(),
56	        lock() {
57	  }
58	};
59	
60	int main(int argc, char *argv[]) {
61	  //We should have at least 2 arguments
62	  if (argc < 2) {
63	    usage();
64	    exit(EXIT_FAILURE);
65	  }
66	
67	  bool recursive = false;
68	  int input;
69	
70	  //Using GetOpt to read in the values
71	  opterr = 0;
72	  while ((input = getopt(argc, argv, "Rh")) != -1) {
73	    switch (input)
74	    {
75	    case 'R':
76	      recursive = true;
77	      break;
78	    case 'h':
79	      usage();
80	      exit(EXIT_SUCCESS);
81	    case '?':
82	      if (isprint(optopt))
83	        std::cerr << "Unknown option `-" << (char) optopt << "'." << std::endl;
84	      else
85	        std::cerr << "Unknown option character `" << (char) optopt << "'." << std::endl;
86	      usage();
87	      exit(EXIT_FAILURE);
88	    default:
89	      exit(EXIT_FAILURE);
90	    }
91	  }
92	  std::string uri_path = argv[optind];
93	
94	  //Building a URI object from the given uri_path
95	  hdfs::URI uri = hdfs::parse_path_or_exit(uri_path);
96	
97	  std::shared_ptr<hdfs::FileSystem> fs = hdfs::doConnect(uri, true);
98	  if (!fs) {
99	    std::cerr << "Could not connect the file system. " << std::endl;
100	    exit(EXIT_FAILURE);
101	  }
102	
103	  /* wrap async FileSystem::GetContentSummary with promise to make it a blocking call */
104	  std::shared_ptr<std::promise<hdfs::Status>> promise = std::make_shared<std::promise<hdfs::Status>>();
105	  std::future<hdfs::Status> future(promise->get_future());
106	  auto handler = [promise](const hdfs::Status &s) {
107	    promise->set_value(s);
108	  };
109	
110	  //Allocating shared state, which includes:
111	  //handler to be called, request counter, and a boolean to keep track if find is done
112	  std::shared_ptr<GetContentSummaryState> state = std::make_shared<GetContentSummaryState>(handler, 0, false);
113	
114	  // Keep requesting more from Find until we process the entire listing. Call handler when Find is done and reques counter is 0.
115	  // Find guarantees that the handler will only be called once at a time so we do not need locking in handlerFind.
116	  auto handlerFind = [fs, state](const hdfs::Status &status_find, const std::vector<hdfs::StatInfo> & stat_infos, bool has_more_results) -> bool {
117	
118	    //For each result returned by Find we call async GetContentSummary with the handler below.
119	    //GetContentSummary DOES NOT guarantee that the handler will only be called once at a time, so we DO need locking in handlerGetContentSummary.
120	    auto handlerGetContentSummary = [state](const hdfs::Status &status_get_summary, const hdfs::ContentSummary &si) {
121	      std::lock_guard<std::mutex> guard(state->lock);
122	      std::cout << si.str_du() << std::endl;
123	      //Decrement the counter once since we are done with this async call
124	      if (!status_get_summary.ok() && state->status.ok()){
125	        //We make sure we set state->status only on the first error.
126	        state->status = status_get_summary;
127	      }
128	      state->request_counter--;
129	      if(state->request_counter == 0 && state->find_is_done){
130	        state->handler(state->status); //exit
131	      }
132	    };
133	    if(!stat_infos.empty() && state->status.ok()) {
134	      for (hdfs::StatInfo const& s : stat_infos) {
135	        //Launch an asynchronous call to GetContentSummary for every returned result
136	        state->request_counter++;
137	        fs->GetContentSummary(s.full_path, handlerGetContentSummary);
138	      }
139	    }
140	
141	    //Lock this section because handlerGetContentSummary might be accessing the same
142	    //shared variables simultaneously
143	    std::lock_guard<std::mutex> guard(state->lock);
144	    if (!status_find.ok() && state->status.ok()){
145	      //We make sure we set state->status only on the first error.
146	      state->status = status_find;
147	    }
148	    if(!has_more_results){
149	      state->find_is_done = true;
150	      if(state->request_counter == 0){
151	        state->handler(state->status); //exit
152	      }
153	      return false;
154	    }
155	    return true;
156	  };
157	
158	  if(!recursive){
159	    //Asynchronous call to Find
160	    fs->GetListing(uri.get_path(), handlerFind);
161	  } else {
162	    //Asynchronous call to Find
163	    fs->Find(uri.get_path(), "*", hdfs::FileSystem::GetDefaultFindMaxDepth(), handlerFind);
164	  }
165	
166	  /* block until promise is set */
167	  hdfs::Status status = future.get();
168	  if (!status.ok()) {
169	    std::cerr << "Error: " << status.ToString() << std::endl;
170	    exit(EXIT_FAILURE);
171	  }
172	
173	  // Clean up static data and prevent valgrind memory leaks
174	  google::protobuf::ShutdownProtobufLibrary();
175	  return 0;
176	}

