29	      << std::endl
30	      << std::endl << "  -R        list subdirectories recursively"
31	      << std::endl << "  -h        display this help and exit"
32	      << std::endl
33	      << std::endl << "Examples:"
34	      << std::endl << "hdfs_ls hdfs://localhost.localdomain:8020/dir"
