39	int main(int argc, char *argv[]) {
40	  //We should have at least 2 arguments
41	  if (argc < 2) {
42	    usage();
43	    exit(EXIT_FAILURE);
44	  }
45	
46	  bool recursive = false;
47	  int input;
48	
49	  //Using GetOpt to read in the values
50	  opterr = 0;
51	  while ((input = getopt(argc, argv, "Rh")) != -1) {
52	    switch (input)
53	    {
54	    case 'R':
55	      recursive = true;
56	      break;
57	    case 'h':
58	      usage();
59	      exit(EXIT_SUCCESS);
60	    case '?':
61	      if (isprint(optopt))
62	        std::cerr << "Unknown option `-" << (char) optopt << "'." << std::endl;
63	      else
64	        std::cerr << "Unknown option character `" << (char) optopt << "'." << std::endl;
65	      usage();
66	      exit(EXIT_FAILURE);
67	    default:
68	      exit(EXIT_FAILURE);
69	    }
70	  }
71	  std::string uri_path = argv[optind];
72	
73	  //Building a URI object from the given uri_path
74	  hdfs::URI uri = hdfs::parse_path_or_exit(uri_path);
75	
76	  std::shared_ptr<hdfs::FileSystem> fs = hdfs::doConnect(uri, true);
77	  if (!fs) {
78	    std::cerr << "Could not connect the file system. " << std::endl;
79	    exit(EXIT_FAILURE);
80	  }
81	
82	  std::shared_ptr<std::promise<void>> promise = std::make_shared<std::promise<void>>();
83	  std::future<void> future(promise->get_future());
84	  hdfs::Status status = hdfs::Status::OK();
85	
86	  /**
87	    * Keep requesting more until we get the entire listing. Set the promise
88	    * when we have the entire listing to stop.
89	    *
90	    * Find and GetListing guarantee that the handler will only be called once at a time,
91	    * so we do not need any locking here. They also guarantee that the handler will be
92	    * only called once with has_more_results set to false.
93	    */
94	  auto handler = [promise, &status]
95	                  (const hdfs::Status &s, const std::vector<hdfs::StatInfo> & si, bool has_more_results) -> bool {
96	    //Print result chunks as they arrive
97	    if(!si.empty()) {
98	      for (hdfs::StatInfo const& s : si) {
99	        std::cout << s.str() << std::endl;
100	      }
101	    }
102	    if(!s.ok() && status.ok()){
103	      //We make sure we set 'status' only on the first error.
104	      status = s;
105	    }
106	    if (!has_more_results) {
107	      promise->set_value();  //set promise
108	      return false;         //request stop sending results
109	    }
110	    return true;  //request more results
111	  };
112	
113	  if(!recursive){
114	    //Asynchronous call to GetListing
115	    fs->GetListing(uri.get_path(), handler);
116	  } else {
117	    //Asynchronous call to Find
118	    fs->Find(uri.get_path(), "*", hdfs::FileSystem::GetDefaultFindMaxDepth(), handler);
119	  }
120	
121	  //block until promise is set
122	  future.get();
123	  if(!status.ok()) {
124	    std::cerr << "Error: " << status.ToString() << std::endl;
125	  }
126	
127	  // Clean up static data and prevent valgrind memory leaks
128	  google::protobuf::ShutdownProtobufLibrary();
129	  return 0;
130	}

