27	      << std::endl
28	      << std::endl << "Changes the replication factor of a file at PATH. If PATH is a directory then the command"
29	      << std::endl << "recursively changes the replication factor of all files under the directory tree rooted at PATH."
30	      << std::endl
31	      << std::endl << "  -h  display this help and exit"
32	      << std::endl
33	      << std::endl << "Examples:"
