35	      << std::endl << "hdfs_setrep 3 /dir1/dir2"
36	      << std::endl;
37	}
38	
39	struct SetReplicationState {
40	  const uint16_t replication;
41	  const std::function<void(const hdfs::Status &)> handler;
42	  //The request counter is incremented once every time SetReplication async call is made
43	  uint64_t request_counter;
44	  //This boolean will be set when find returns the last result
45	  bool find_is_done;
46	  //Final status to be returned
47	  hdfs::Status status;
48	  //Shared variables will need protection with a lock
49	  std::mutex lock;
50	  SetReplicationState(const uint16_t replication_, const std::function<void(const hdfs::Status &)> & handler_,
51	              uint64_t request_counter_, bool find_is_done_)
52	      : replication(replication_),
53	        handler(handler_),
54	        request_counter(request_counter_),
55	        find_is_done(find_is_done_),
56	        status(),
57	        lock() {
58	  }
59	};
60	
61	int main(int argc, char *argv[]) {
62	  //We should have 3 or 4 parameters
63	  if (argc < 3) {
64	    usage();
65	    exit(EXIT_FAILURE);
66	  }
67	
68	  int input;
69	
70	  //Using GetOpt to read in the values
71	  opterr = 0;
72	  while ((input = getopt(argc, argv, "h")) != -1) {
73	    switch (input)
74	    {
75	    case 'h':
76	      usage();
77	      exit(EXIT_SUCCESS);
78	    case '?':
79	      if (isprint(optopt))
80	        std::cerr << "Unknown option `-" << (char) optopt << "'." << std::endl;
81	      else
82	        std::cerr << "Unknown option character `" << (char) optopt << "'." << std::endl;
83	      usage();
84	      exit(EXIT_FAILURE);
85	    default:
86	      exit(EXIT_FAILURE);
87	    }
88	  }
89	  std::string repl = argv[optind];
90	  std::string uri_path = argv[optind + 1];
91	
92	  //Building a URI object from the given uri_path
93	  hdfs::URI uri = hdfs::parse_path_or_exit(uri_path);
94	
95	  std::shared_ptr<hdfs::FileSystem> fs = hdfs::doConnect(uri, true);
96	  if (!fs) {
97	    std::cerr << "Could not connect the file system. " << std::endl;
98	    exit(EXIT_FAILURE);
99	  }
100	
101	  /* wrap async FileSystem::SetReplication with promise to make it a blocking call */
102	  std::shared_ptr<std::promise<hdfs::Status>> promise = std::make_shared<std::promise<hdfs::Status>>();
103	  std::future<hdfs::Status> future(promise->get_future());
104	  auto handler = [promise](const hdfs::Status &s) {
105	    promise->set_value(s);
106	  };
107	
108	  uint16_t replication = std::stoi(repl.c_str(), NULL, 8);
109	  //Allocating shared state, which includes:
110	  //replication to be set, handler to be called, request counter, and a boolean to keep track if find is done
111	  std::shared_ptr<SetReplicationState> state = std::make_shared<SetReplicationState>(replication, handler, 0, false);
112	
113	  // Keep requesting more from Find until we process the entire listing. Call handler when Find is done and reques counter is 0.
114	  // Find guarantees that the handler will only be called once at a time so we do not need locking in handlerFind.
115	  auto handlerFind = [fs, state](const hdfs::Status &status_find, const std::vector<hdfs::StatInfo> & stat_infos, bool has_more_results) -> bool {
116	
117	    //For each result returned by Find we call async SetReplication with the handler below.
118	    //SetReplication DOES NOT guarantee that the handler will only be called once at a time, so we DO need locking in handlerSetReplication.
119	    auto handlerSetReplication = [state](const hdfs::Status &status_set_replication) {
120	      std::lock_guard<std::mutex> guard(state->lock);
121	
122	      //Decrement the counter once since we are done with this async call
123	      if (!status_set_replication.ok() && state->status.ok()){
124	        //We make sure we set state->status only on the first error.
125	        state->status = status_set_replication;
126	      }
127	      state->request_counter--;
128	      if(state->request_counter == 0 && state->find_is_done){
129	        state->handler(state->status); //exit
130	      }
131	    };
132	    if(!stat_infos.empty() && state->status.ok()) {
133	      for (hdfs::StatInfo const& s : stat_infos) {
134	        //Launch an asynchronous call to SetReplication for every returned file
135	        if(s.file_type == hdfs::StatInfo::IS_FILE){
136	          state->request_counter++;
137	          fs->SetReplication(s.full_path, state->replication, handlerSetReplication);
138	        }
139	      }
140	    }
141	
142	    //Lock this section because handlerSetReplication might be accessing the same
143	    //shared variables simultaneously
144	    std::lock_guard<std::mutex> guard(state->lock);
145	    if (!status_find.ok() && state->status.ok()){
146	      //We make sure we set state->status only on the first error.
147	      state->status = status_find;
148	    }
149	    if(!has_more_results){
150	      state->find_is_done = true;
151	      if(state->request_counter == 0){
152	        state->handler(state->status); //exit
153	      }
154	      return false;
155	    }
156	    return true;
157	  };
158	
159	  //Asynchronous call to Find
160	  fs->Find(uri.get_path(), "*", hdfs::FileSystem::GetDefaultFindMaxDepth(), handlerFind);
161	
162	  /* block until promise is set */
163	  hdfs::Status status = future.get();
164	  if (!status.ok()) {
165	    std::cerr << "Error: " << status.ToString() << std::endl;
166	    exit(EXIT_FAILURE);
167	  }
168	
169	  // Clean up static data and prevent valgrind memory leaks
170	  google::protobuf::ShutdownProtobufLibrary();
171	  return 0;
172	}

