26	      << std::endl
27	      << std::endl << "Displays last kilobyte of the file to stdout."
28	      << std::endl
29	      << std::endl << "  -f  output appended data as the file grows, as in Unix"
30	      << std::endl << "  -h  display this help and exit"
31	      << std::endl
32	      << std::endl << "Examples:"
33	      << std::endl << "hdfs_tail hdfs://localhost.localdomain:8020/dir/file"
34	      << std::endl << "hdfs_tail /dir/file"
35	      << std::endl;
36	}
37	
38	#define TAIL_SIZE 1024
39	#define REFRESH_RATE 1 //seconds
40	
41	int main(int argc, char *argv[]) {
42	  if (argc < 2) {
43	    usage();
44	    exit(EXIT_FAILURE);
45	  }
46	
47	  bool follow = false;
48	  int input;
49	
50	  //Using GetOpt to read in the values
51	  opterr = 0;
52	  while ((input = getopt(argc, argv, "hf")) != -1) {
53	    switch (input)
54	    {
55	    case 'h':
56	      usage();
57	      exit(EXIT_SUCCESS);
58	    case 'f':
59	      follow = true;
60	      break;
61	    case '?':
62	      if (isprint(optopt))
63	        std::cerr << "Unknown option `-" << (char) optopt << "'." << std::endl;
64	      else
65	        std::cerr << "Unknown option character `" << (char) optopt << "'." << std::endl;
66	      usage();
67	      exit(EXIT_FAILURE);
68	    default:
69	      exit(EXIT_FAILURE);
70	    }
71	  }
72	
73	  std::string uri_path = argv[optind];
74	
75	  //Building a URI object from the given uri_path
76	  hdfs::URI uri = hdfs::parse_path_or_exit(uri_path);
77	
78	  std::shared_ptr<hdfs::FileSystem> fs = hdfs::doConnect(uri, false);
79	  if (!fs) {
80	    std::cerr << "Could not connect the file system. " << std::endl;
81	    exit(EXIT_FAILURE);
82	  }
83	
84	  //We need to get the size of the file using stat
85	  hdfs::StatInfo stat_info;
86	  hdfs::Status status = fs->GetFileInfo(uri.get_path(), stat_info);
87	  if (!status.ok()) {
88	    std::cerr << "Error: " << status.ToString() << std::endl;
89	    exit(EXIT_FAILURE);
90	  }
91	
92	  //Determine where to start reading
93	  off_t offset = 0;
94	  if(stat_info.length > TAIL_SIZE){
95	    offset = stat_info.length - TAIL_SIZE;
96	  }
97	
98	  do {
99	    off_t current_length = (off_t) stat_info.length;
100	    readFile(fs, uri.get_path(), offset, stdout, false);
101	
102	    //Exit if -f flag was not set
103	    if(!follow){
104	      break;
105	    }
106	
107	    do{
108	      //Sleep for the REFRESH_RATE
109	      sleep(REFRESH_RATE);
110	      //Use stat to check the new filesize.
111	      status = fs->GetFileInfo(uri.get_path(), stat_info);
112	      if (!status.ok()) {
113	        std::cerr << "Error: " << status.ToString() << std::endl;
114	        exit(EXIT_FAILURE);
115	      }
116	      //If file became longer, loop back and print the difference
117	    }
118	    while((off_t) stat_info.length <= current_length);
119	  } while (true);
120	
121	  // Clean up static data and prevent valgrind memory leaks
122	  google::protobuf::ShutdownProtobufLibrary();
123	  return 0;
124	}

