namespace hdfs::tools {
/**
 * {@class Du} is an {@class HdfsTool} that displays sizes of files and
 * directories contained in the given directory or the length of a file in
 * case its just a file.
 */
class Du : public HdfsTool {
public:
  /**
   * {@inheritdoc}
   */
  Du(int argc, char **argv);

  // Abiding to the Rule of 5
  Du(const Du &) = default;
  Du(Du &&) = default;
  Du &operator=(const Du &) = delete;
  Du &operator=(Du &&) = delete;
  ~Du() override = default;

